theorem iterN_done_unique {body : α → TRes α} {c : α → TRes Bool} {n m : Nat} {σ : α}
    {r r' : TRes α} (h : iterN body c n σ = .inr r) (h' : iterN body c m σ = .inr r') :
    r = r'

theorem TRun.catchBytes_ne_panic {ρ ps Γf : Ctx} {c : ExtCall C Γ} {rets : Binders ρ}
    {sargs : Args C Γ ps} {hs : Ext (ρ ++ ps) Γf} {sbody : TStep C (ρ ++ ps) Γf} {self : Bool}
    {σ : State C Γ} {e : THalt} (h : TRun.catchBytes c rets sargs hs sbody self σ = .error e) :
    e ≠ .panic

theorem Prog.run_cons_ok {Γ₁ Γ₂ : Ctx} {σ : State C Γ} {o : Out C σ.H Γ₁} {s : Stmt C Γ Γ₁}
    {P : Prog C Γ₁ Γ₂} (h : s.run σ = .ok o) :
    Prog.run σ (.cons s P) = (Prog.run o.st P).map fun o' => ⟨o'.st, o.ext.trans o'.ext⟩

theorem opStoreT_frame {σ : State C Γ} (op : BinOp) {p : PrimTy} {r : SRef C (.prim p)}
    {v : p.Denote} {o : Out C σ.H Γ} (h : opStoreT σ op r v = .ok o) :
    TGFrame .nonpayable σ o.st ∧ TLocAgree 0 [] σ.env o.st.env

theorem bumpStoreT_frame {σ : State C Γ} (op : IncDec) {p : PrimTy} {r : SRef C (.prim p)}
    {o : Out C σ.H Γ} {w : p.Denote} (h : bumpStoreT σ op r = .ok (o, w)) :
    TGFrame .nonpayable σ o.st ∧ TLocAgree 0 [] σ.env o.st.env

theorem OpLoc.storeT_frame {p : PrimTy} (op : BinOp) (l : OpLoc C Γ p) (d : Nat) {σ : State C Γ}
    {v : p.Denote} {o : Out C σ.H Γ} (hl : l.writableIn μ = true) (h : l.storeT σ op v = .ok o) :
    TGFrame μ σ o.st ∧ TLocAgree d (l.writesAt d) σ.env o.st.env

theorem OpLoc.bumpT_frame {p : PrimTy} (op : IncDec) (l : OpLoc C Γ p) (d : Nat) {σ : State C Γ}
    {o : Out C σ.H Γ} {w : p.Denote} (hl : l.writableIn μ = true) (h : l.bumpT σ op = .ok (o, w)) :
    TGFrame μ σ o.st ∧ TLocAgree d (l.writesAt d) σ.env o.st.env

theorem same {hv : Option (List Name)} {σ : State C Γ} {τ : State C Δ}
    (hs : τ.storage = σ.storage) (hn : τ.net = σ.net) (hb : τ.selfBalance = σ.selfBalance) :
    FrameKeeps hv σ τ

theorem Loc.resolveT_storeAt {Γ : Ctx} {σ : State C Γ} {T : Ty} {l : Loc C Γ T}
    {r : SRef C T} (h : l.resolveT σ = .ok r) {L : List Name} (hL : l.storeAt = some L) :
    r.root ∈ L

theorem SPath.resolveT_storeAt {Γ : Ctx} {σ : State C Γ} {T : Ty} {b : SPath C Γ T}
    {r : SRef C T} (h : b.resolveT σ = .ok r) {L : List Name} (hL : b.root?.map ([·]) = some L) :
    r.root ∈ L

theorem opStoreT_keeps {Γ : Ctx} {σ : State C Γ} (op : BinOp) {p : PrimTy}
    {r : SRef C (.prim p)} {v : p.Denote} {o : Out C σ.H Γ} {L : List Name} (hr : r.root ∈ L)
    (h : opStoreT σ op r v = .ok o) : FrameKeeps (some L) σ o.st

theorem bumpStoreT_keeps {Γ : Ctx} {σ : State C Γ} (op : IncDec) {p : PrimTy}
    {r : SRef C (.prim p)} {o : Out C σ.H Γ} {w : p.Denote} {L : List Name} (hr : r.root ∈ L)
    (h : bumpStoreT σ op r = .ok (o, w)) : FrameKeeps (some L) σ o.st

theorem State.eq_anonHavoc {σ τ : State C Γ} {xs : List ((t : LTy) × Idx Γ t)} {μ : Mutability}
    {W : List (LTy × Nat)}
    (hxs : ∀ t (i : Idx Γ t), (t, i.toNat) ∈ W → (⟨t, i⟩ : (t : LTy) × Idx Γ t) ∈ xs)
    (hg : TGFrame μ σ τ) (ha : TLocAgree 0 W σ.env τ.env) :
    ∃ b, τ = (σ.anon xs b).havoc τ.storage τ.net τ.selfBalance

theorem Prog.frame_keeps {Γ₁ : Ctx} {P : Prog C Γ Γ₁} {xs : List ((t : LTy) × Idx Γ t)}
    {hv : Option (List Name)} (hf : P.frame = some (xs, hv)) {σ : State C Γ}
    {o : Out C σ.H Γ₁} (h : Prog.run σ P = .ok o) : FrameKeeps hv σ (o.st.drop P.ext)

theorem source_local_alias_low_horizon {E : Source.Env} {Γ : Source.RCtx} {τ : Source.STy}
    (G : Source.Glob E) (F : Source.Fr) (y : Source.EMState E Γ) (dst src : Source.Idx Γ τ) :
    ∀ n, n≤1 → (Source.evalE G F n (sourceLocalAlias dst src)).run y=(.error .timeout,y)
